use serde_json::json;use std::collections::BTreeMap;
pub const MAX_PAYLOAD_BYTES:usize=32768;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Direction{Clientbound,Serverbound,Bidirectional}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct PayloadType{pub id:String,pub direction:Direction,pub max_bytes:usize,pub codec_id:String}
#[derive(Default)]pub struct PayloadRegistry{types:BTreeMap<String,PayloadType>}
impl PayloadRegistry{pub fn register(&mut self,p:PayloadType)->Result<(),String>{if !valid_id(&p.id)||p.codec_id.is_empty()||p.codec_id.len()>128{return Err("invalid_payload_type".into());}if p.max_bytes==0||p.max_bytes>MAX_PAYLOAD_BYTES{return Err("payload_size_out_of_bounds".into());}if self.types.contains_key(&p.id){return Err("duplicate_payload_type".into());}self.types.insert(p.id.clone(),p);Ok(())}pub fn validate(&self,id:&str,data:&[u8])->Result<(),String>{let p=self.types.get(id).ok_or_else(||"unknown_payload_type".to_owned())?;if data.len()>p.max_bytes{return Err("payload_too_large".into());}Ok(())}pub fn report(&self)->serde_json::Value{json!({"mode":"codec-registration-contract-only","horizon_packet_dispatcher_connected":false,"max_payload_bytes":MAX_PAYLOAD_BYTES,"registered_types":self.types.values().map(|v|json!({"id":v.id,"direction":format!("{:?}",v.direction),"max_bytes":v.max_bytes,"codec_id":v.codec_id})).collect::<Vec<_>>()})}}
fn valid_id(v:&str)->bool{if v.is_empty()||v.len()>256{return false;}let(ns,p)=v.split_once(':').unwrap_or(("minecraft",v));!ns.is_empty()&&!p.is_empty()&&ns.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'|b'.'))&&!p.starts_with('/')&&!p.ends_with('/')&&p.split('/').all(|part|!part.is_empty()&&part!="."&&part!="..")&&p.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'|b'.'|b'/'))}
#[cfg(test)]mod tests{use super::*;#[test]fn payload_limits_are_enforced(){let mut r=PayloadRegistry::default();r.register(PayloadType{id:"naturescompass:search".into(),direction:Direction::Serverbound,max_bytes:8,codec_id:"codec-v1".into()}).unwrap();assert!(r.validate("naturescompass:search",&[0;8]).is_ok());assert_eq!(r.validate("naturescompass:search",&[0;9]),Err("payload_too_large".into()));}}
